import math

def count_divisors(n):
    if n == 1:
        return 1
    count = 0
    # Iterate up to sqrt(n)
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

